insert into public.submissions (id, team_id, stage, status, title, sdg_tags, problem_statement, methodology, links, technical_reasoning, prototype_status, test_outcomes, evidence_links, submitted_at, updated_at) values
  ('f0000000-0000-4000-8000-000000000004', 'd0000000-0000-4000-8000-000000000002', 2, 'submitted',
   'JalSaathi: Greywater Recycling for School Washrooms',
   '{SDG 6,SDG 12}',
   'Our school of 1,200 students wastes roughly 8,000 litres of washbasin water daily, while the garden needs 2 tanker deliveries a week in summer.',
   '1. Measure actual basin outflow across one week. 2. Design a two-stage filter (gravel-charcoal-sand then UV lamp) plumbed from washroom basins to a 1,000 L garden tank. 3. Test water quality before and after with pool test strips. 4. Cost the retrofit from local plumbing suppliers.',
   'https://drive.google.com/demo/jal-flow-diagram',
   'The two-stage design keeps maintenance to a monthly charcoal swap, which the maintenance staff can perform. The 12 V UV lamp draws 6 W, supplied by a small solar panel — no wiring changes needed.',
   'Full pilot installed on one washroom bank; school board approved scaling to two more after summer break.',
   'Total water recovered in the 3-week trial: 26,400 litres. Tanker deliveries dropped from 8 to 3. Payback estimated at 14 months.',
   'https://picsum.photos/seed/jalsaathi/900/600', now() - interval '3 days', now() - interval '3 days'),
  ('f0000000-0000-4000-8000-000000000005', 'd0000000-0000-4000-8000-000000000003', 1, 'submitted',
   'DawaDot: Sticker-based Medicine Schedule for Elders',
   '{SDG 3}',
   'Grandparents in our neighbourhood miss doses because printed schedules are confusing — 6 of 10 elders we interviewed missed medication at least twice a week.',
   '1. Interview 10 elders and 3 pharmacists about missed doses. 2. Design large-print day/night sticker strips that pharmacists attach to medicine strips. 3. Run a 4-week diary study with 8 families. 4. Publish the printable template free for any pharmacy.',
   'https://drive.google.com/demo/dawadot-templates',
   null, null, null, null, now() - interval '4 days', now() - interval '4 days'),
  ('f0000000-0000-4000-8000-000000000006', 'd0000000-0000-4000-8000-000000000004', 1, 'draft',
   'Pathshala Radio: Local-language Audio Lessons',
   '{SDG 4}',
   'Students in the government school nearby struggle with English-medium online content; our survey found 70% prefer audio lessons in Hindi.',
   null, null, null, null, null, null, null, now() - interval '1 day');
